parameters.jsCode:
const now = new Date().toISOString();
let combinedObjections = [];

for (const item of $input.all()) {
  let raw = item.json.output;

  raw = raw.trim();
  if (raw.startsWith("```json")) {
    raw = raw.slice(7);
  }
  if (raw.endsWith("```")) {
    raw = raw.slice(0, -3);
  }
  raw = raw.trim();

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    continue; // ignora item se não der pra parsear
  }

  if (parsed && Array.isArray(parsed.triggers)) {
    combinedObjections.push(...parsed.triggers);
  }
}

return {
  timestamp: now,
  triggers: combinedObjections
};

parameters.inputSchema:
{
  "type": "array",
  "items": {
    "type": "object",
    "properties": {
      "topic": {
        "type": "string",
        "description": "Nome do tópico identificado na conversa"
      },
      "conversations": {
        "type": "number",
        "description": "Quantidade de conversas em que esse tópico foi mencionado"
      }
    },
    "required": ["topic", "conversations"]
  }
}

