const now = new Date().toISOString();

let raw = $input.all()[0].json.output;

if (!raw) return { timestamp: now, topics: [] };

raw = raw.trim();
if (raw.startsWith("```json")) raw = raw.slice(7);
if (raw.endsWith("```")) raw = raw.slice(0, -3);
raw = raw.trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return { timestamp: now, error: "Falha ao parsear JSON" };
}

// extrai apenas o array de topics
const topics = (parsed.topics && parsed.topics.topics) || [];

return { timestamp: now, topics };

// n8n Code node
// Mode: Run Once for All Items

const items = $input.all();

const uuidRegex =
  /\(([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\)/i;

const uuids = new Set();

for (const item of items) {
  const data = item.json?.data;

  if (!data || typeof data !== 'object') continue;

  for (const key of Object.keys(data)) {
    const match = key.match(uuidRegex);
    if (match) {
      uuids.add(match[1]);
    }
  }
}

return [
  {
    json: {
      uuids: [...uuids],
    },
  },
];

const items = $input.all();

function parseTopics(topicsRaw) {
  if (typeof topicsRaw !== 'string') return null;

  const cleaned = topicsRaw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');

  try {
    return JSON.parse(cleaned);
  } catch {
    throw new Error('Invalid JSON inside topics field');
  }
}

// 🔑 extract UUID from strings like "Name (uuid)"
function extractUuid(value) {
  if (typeof value !== 'string') return null;
  const match = value.match(
    /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i
  );
  return match ? match[0] : null;
}

return items.map(item => {
  const uuids = Array.isArray(item.json.uuids) ? item.json.uuids : [];
  const uuidSet = new Set(uuids.map(String));

  const parsedTopics = parseTopics(item.json.topics);
  if (!parsedTopics?.topics) return item;

  const cleanedTopics = parsedTopics.topics.map(topic => {
    const validDetails = (topic.details || []).filter(d => {
      const extractedUuid = extractUuid(d.lead_id);
      return extractedUuid && uuidSet.has(extractedUuid);
    });

    return {
      ...topic,
      details: validDetails,
      conversations: validDetails.length
    };
  });

  return {
    json: {
      ...item.json,
      topics: {
        topics: cleanedTopics
      }
    }
  };
});

