for (const item of $input.all()) {
  let raw = item.json.output;

  if (!raw) continue;

  // --- Remove marcações de bloco de código (```json ... ```)
  raw = raw.trim();
  if (raw.startsWith("```json")) raw = raw.slice(7);
  if (raw.endsWith("```")) raw = raw.slice(0, -3);
  raw = raw.trim();

  // --- Remove quebras de linha e escapes desnecessários
  raw = raw.replace(/\\n/g, "\n").replace(/\r/g, "").trim();

  let parsed;

  try {
    parsed = JSON.parse(raw);
    if (typeof parsed === "string") {
      parsed = JSON.parse(parsed);
    }
  } catch (e) {
    try {
      const cleaned = raw.replace(/\\"/g, '"').replace(/\\\\/g, '\\');
      parsed = JSON.parse(cleaned);
    } catch (err2) {
      continue; // pula se não conseguir parsear
    }
  }

  // --- Garante que parsed seja um array ou objeto
  if (Array.isArray(parsed)) {
    for (const entry of parsed) {
      flattened.push({
        json: {
          analysis: entry.analysis
        },
      });
    }
  } else if (typeof parsed === "object" && parsed !== null) {
    flattened.push({
      json: {
        analysis: parsed.analysis
      },
    });
  }
}

return flattened;

let flattened = [];

for (const item of $input.all()) {
