  raw = raw.trim();
  if (raw.startsWith("```json")) raw = raw.slice(7);
  if (raw.endsWith("```")) raw = raw.slice(0, -3);
  raw = raw.trim();

  // --- Remove quebras de linha e espaços estranhos
  raw = raw.replace(/\\n/g, "\n").replace(/\r/g, "").trim();

  let parsed;

  try {
    // --- Tenta fazer o parse diretamente
    parsed = JSON.parse(raw);

    // --- Se ainda for string, tenta parsear de novo (caso haja escape duplo)
    if (typeof parsed === "string") {
      parsed = JSON.parse(parsed);
    }
  } catch (e) {
    // --- Se ainda falhar, tenta remover escapes manuais e tentar mais uma vez
    try {
      const cleaned = raw.replace(/\\"/g, '"').replace(/\\\\/g, '\\');
      parsed = JSON.parse(cleaned);
    } catch (err2) {
      continue; // pula se não conseguir parsear de jeito nenhum
    }
  }

  // --- Garante que temos um array
  if (!Array.isArray(parsed)) continue;

  for (const entry of parsed) {
    flattened.push({
      json: {
        lead_id: entry.lead_id,
        lead_name: entry.lead_name,
        ai_suggestion: {
          suggested_action_to_convert_lead: entry.suggested_action_to_convert_lead,
          suggestion_explanation: entry.suggestion_explanation,
        },
      },
    });
  }
}

return flattened;

function cleanMarkdown(text) {
  if (typeof text !== 'string') return '';

  let cleaned = text.trim();

  // Remove ```json ou ``` do início
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```json\s*/i, '');
    cleaned = cleaned.replace(/^```\s*/i, '');
  }

  // Remove ``` do final
  if (cleaned.endsWith('```')) {
    cleaned = cleaned.replace(/\s*```$/, '');
  }

  return cleaned.trim();
}

function safeJsonParse(text) {
  try {
    const parsed = JSON.parse(text);
    return parsed;
  } catch (e) {
    return null;
  }
}

const results = [];

for (const item of items) {
  const rawOutput = item.json?.output;

  const cleaned = cleanMarkdown(rawOutput);
  const parsed = safeJsonParse(cleaned);

  // Sempre manter o formato { output: [...] }
  if (Array.isArray(parsed)) {
    results.push({
      json: {
        output: parsed
      }
    });
  } else {
    // fallback seguro
    results.push({
      json: {
        output: []
      }
    });
  }
}

return results;

