let keywords = [];

for (const item of $input.all()) {
  let raw = item.json.output;

  // Remove marcações ```json e ```
  raw = raw.trim();
  if (raw.startsWith("```json")) {
    raw = raw.slice(7);
  }
  if (raw.endsWith("```")) {
    raw = raw.slice(0, -3);
  }
  raw = raw.trim();

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    continue;
  }

  // Converte objeto em array de objetos com chave 'topic'
  for (const [topic, data] of Object.entries(parsed)) {
    keywords.push({
      topic,
      number_of_occurrences: data.number_of_occurrences,
      engagement_rate: data.engagement_rate
    });
  }
}

return {
  keywords
};

