parameters.jsCode:
const items = $input.all();

function parseTopics(raw) {
  if (typeof raw !== 'string') return null;

  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');

  try {
    return JSON.parse(cleaned);
  } catch {
    throw new Error('Invalid JSON inside objections field');
  }
}

return items.map(item => {
  const uuids = Array.isArray(item.json.uuids) ? item.json.uuids : [];
  const uuidSet = new Set(uuids);

  const parsedTopics = parseTopics(item.json.objections);

  if (!parsedTopics?.objections) {
    return {
      json: {
        uuids,
        objections: { objections: [] }
      }
    };
  }

  const cleanedObjections = parsedTopics.objections.map(obj => {
    const validDetails = (obj.details || []).filter(d =>
      uuidSet.has(d.lead_id)
    );

    return {
      ...obj,
      details: validDetails,
      conversations: validDetails.length
    };
  });

  return {
    json: {
      uuids,
      objections: {
        objections: cleanedObjections
      }
    }
  };
});

// n8n Code node
// Mode: Run Once for All Items

const items = $input.all();

const uuidRegex =
  /\(([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\)/i;

const uuids = new Set();

for (const item of items) {
  const data = item.json?.data;

  if (!data || typeof data !== 'object') continue;

  for (const key of Object.keys(data)) {
    const match = key.match(uuidRegex);
    if (match) {
      uuids.add(match[1]);
    }
  }
}

return [
  {
    json: {
      uuids: [...uuids],
    },
  },
];

