const now = new Date().toISOString();
let flattened = [];

for (const item of $input.all()) {
  let raw = item.json.output;

  raw = raw.trim();
  if (raw.startsWith("```json")) {
    raw = raw.slice(7);
  }
  if (raw.endsWith("```")) {
    raw = raw.slice(0, -3);
  }

  raw = raw.trim();

  let outputArray;
  try {
    outputArray = JSON.parse(raw);
  } catch (e) {
    continue;
  }

  if (Array.isArray(outputArray)) {
    flattened.push(...outputArray);
  }
}

return {
  timestamp: now,
  topics: flattened
};

