const inputData = $input.all();

// Get the two items from input
const item1 = inputData[0].json;
const item2 = inputData[1]?.json || {};

// Merge the data from both items
const data = {...item1, ...item2};

// Get the components
const llm_run_data = data.llm_run_data || {};
const tokensByModel = data.tokensByModel || {};
const model_price_dic = data.model_price_dic || {};

// Deep copy and add costs to llm_run_data
const updated_llm_run_data = {};
Object.keys(llm_run_data).forEach(key => {
  const item = JSON.parse(JSON.stringify(llm_run_data[key]));
  const model = item.options?.model || item.model || 'unknown';
  const prices = model_price_dic[model];

  if (prices && item.tokenUsage) {
    const promptTokens = item.tokenUsage.promptTokens || 0;
    const completionTokens = item.tokenUsage.completionTokens || 0;

    // Calculate costs (price is per million tokens)
    const input_cost = (promptTokens / 1000000) * prices.input;
    const output_cost = (completionTokens / 1000000) * prices.output;

    item.tokenUsage_cost = {
      input_cost: input_cost,
      output_cost: output_cost,
      total_cost: input_cost + output_cost
    };
  } else {
    item.tokenUsage_cost = {
      input_cost: 0,
      output_cost: 0,
      total_cost: 0
    };
  }
  updated_llm_run_data[key] = item;
});

// Deep copy and add costs to tokensByModel
const updated_tokensByModel = {};
Object.keys(tokensByModel).forEach(model => {
  const modelData = JSON.parse(JSON.stringify(tokensByModel[model]));
  const prices = model_price_dic[model];

  if (prices) {
    const promptTokens = modelData.promptTokens || 0;
    const completionTokens = modelData.completionTokens || 0;

    // Calculate costs (price is per million tokens)
    const input_cost = (promptTokens / 1000000) * prices.input;
    const output_cost = (completionTokens / 1000000) * prices.output;

    modelData.input_cost = input_cost;
    modelData.output_cost = output_cost;
    modelData.total_cost = input_cost + output_cost;
  } else {
    modelData.input_cost = 0;
    modelData.output_cost = 0;
    modelData.total_cost = 0;
  }
  updated_tokensByModel[model] = modelData;
});

// Calculate total costs across all models
let total_input_cost = 0;
let total_output_cost = 0;

Object.values(updated_tokensByModel).forEach(modelData => {
  total_input_cost += modelData.input_cost || 0;
  total_output_cost += modelData.output_cost || 0;
});

const cost = {
  input_cost: total_input_cost,
  output_cost: total_output_cost,
  total_cost: total_input_cost + total_output_cost
};

// Return merged data with updates
return [{
  json: {
    ...data,
    llm_run_data: updated_llm_run_data,
    tokensByModel: updated_tokensByModel,
    cost: cost
  }
}];

/**
 * n8n JavaScript Code - Hybrid Version (ai_languageModel + Gemini usageMetadata)
 *
 * n8n often stores the LM request (including options.model) under execution.inputOverride,
 * while execution.data.ai_languageModel only has the response (tokenUsage, etc.).
 * This script mirrors indices (i, ii, iii) into inputOverride to resolve the model.
 */

const inputData = $input.first().json;

const runData =
  inputData.resultData?.runData ||
  inputData.data?.resultData?.runData ||
  inputData.runData;

if (!runData) {
  return [
    {
      json: {
        error: 'Could not find runData in input',
      },
    },
  ];
}

const all_nodes_summary = [];
const llm_run_data = {};
const tokensByModel = {};

function ensureModel(model) {
  if (!tokensByModel[model]) {
    tokensByModel[model] = {
      count: 0,
      estimatedTokens: 0,
      actualTokens: 0,
      completionTokens: 0,
      promptTokens: 0,
    };
  }
}

/**
 * Collects every `ai_languageModel` branch on `obj` (top-level or one level deep).
 * @param {Record<string, unknown> | null | undefined} obj
 * @param {number} depth
 * @returns {unknown[]}
 */
function findAILanguageModel(obj, depth = 0) {
  const found = [];

  if (!obj || depth > 1) {
    return found;
  }

  if (obj.ai_languageModel) {
    found.push(obj.ai_languageModel);
  }

  if (depth === 0) {
    Object.keys(obj).forEach((key) => {
      if (typeof obj[key] === 'object' && obj[key]) {
        if (obj[key].ai_languageModel) {
          found.push(obj[key].ai_languageModel);
        }
      }
    });
  }

  return found;
}

/**
 * Reads the input-side json for the same LM cell as the output (n8n pairs inputOverride with data).
 * @param {Record<string, unknown>} execution
 * @param {number} i index in findAILanguageModel(execution.inputOverride)
 * @param {number} ii outer list index
 * @param {number} iii inner list index
 * @returns {Record<string, unknown> | null}
 */
function getLanguageModelInputMirrorJson(execution, i, ii, iii) {
  const io = execution?.inputOverride;
  if (!io || typeof io !== 'object') {
    return null;
  }
  const lists = findAILanguageModel(io);
  const outerList = lists[i];
  if (!Array.isArray(outerList)) {
    return null;
  }
  const innerList = outerList[ii];
  if (!Array.isArray(innerList)) {
    return null;
  }
  const entry = innerList[iii];
  return entry && typeof entry.json === 'object' ? entry.json : null;
}

/**
 * Model id from LM node output or input json (LangChain / Google node shapes).
 * @param {Record<string, unknown> | null | undefined} json
 * @returns {string | null}
 */
function extractModelNameFromLanguageModelJson(json) {
  if (!json || typeof json !== 'object') {
    return null;
  }

  const o = json.options;
  if (o && typeof o === 'object' && typeof o.model === 'string' && o.model.length > 0) {
    return o.model;
  }

  for (const k of ['model', 'modelName', 'model_id']) {
    const v = json[k];
    if (typeof v === 'string' && v.length > 0) {
      return v;
    }
  }

  const rm = json.response_metadata;
  if (rm && typeof rm === 'object') {
    for (const k of ['model_name', 'model', 'lc_model_name']) {
      const v = rm[k];
      if (typeof v === 'string' && v.length > 0) {
        return v;
      }
    }
  }

  const lc = json.lc_kwargs;
  if (lc && typeof lc === 'object') {
    if (typeof lc.model === 'string' && lc.model.length > 0) {
      return lc.model;
    }
    if (lc.model && typeof lc.model === 'object' && typeof lc.model.modelName === 'string') {
      return lc.model.modelName;
    }
    if (typeof lc.modelName === 'string' && lc.modelName.length > 0) {
      return lc.modelName;
    }
  }

  const kwargs = json.kwargs;
  if (kwargs && typeof kwargs === 'object') {
    if (typeof kwargs.model === 'string' && kwargs.model.length > 0) {
      return kwargs.model;
    }
    if (typeof kwargs.modelName === 'string' && kwargs.modelName.length > 0) {
      return kwargs.modelName;
    }
  }

  return null;
}

/**
 * Resolves model for one ai_languageModel output item, including inputOverride mirror.
 * @param {Record<string, unknown>} execution
 * @param {Record<string, unknown>} item
 * @param {number} i
 * @param {number} ii
 * @param {number} iii
 * @returns {string}
 */
function resolveLanguageModelName(execution, item, i, ii, iii) {
  const fromOut = extractModelNameFromLanguageModelJson(item?.json);
  if (fromOut) {
    return fromOut;
  }
  const inputJson = getLanguageModelInputMirrorJson(execution, i, ii, iii);
  const fromIn = extractModelNameFromLanguageModelJson(inputJson);
  return fromIn || 'unknown';
}

/**
 * Model for Gemini native usageMetadata on main branch.
 * @param {Record<string, unknown> | null | undefined} json
 * @returns {string}
 */
function extractModelNameFromUsageMetadataJson(json) {
  if (!json || typeof json !== 'object' || !json.usageMetadata) {
    return 'gemini_unknown';
  }
  const v =
    json.modelVersion ||
    json.model ||
    json.modelName ||
    (json.response && typeof json.response === 'object' ? json.response.modelVersion : null);
  return typeof v === 'string' && v.length > 0 ? v : 'gemini_unknown';
}

Object.keys(runData).forEach((nodeName) => {
  const executions = runData[nodeName];

  executions.forEach((execution, idx) => {
    all_nodes_summary.push({
      nodeName,
      arrayIndex: idx,
      startTime: execution.startTime,
      executionTime: execution.executionTime,
      executionIndex: execution.executionIndex,
      executionStatus: execution.executionStatus,
    });

    const items = execution?.data?.main || [];

    items.forEach((outer, i) => {
      if (!Array.isArray(outer)) {
        return;
      }

      outer.forEach((item, ii) => {
        const json = item?.json;

        if (!json) {
          return;
        }

        if (json.usageMetadata) {
          const model = extractModelNameFromUsageMetadataJson(json);
          const key = `llm_${nodeName}_${idx}_${i}_${ii}`;

          llm_run_data[key] = {
            type: 'gemini',
            model,
            promptTokens: json.usageMetadata.promptTokenCount || 0,
            completionTokens: json.usageMetadata.candidatesTokenCount || 0,
            totalTokens: json.usageMetadata.totalTokenCount || 0,
          };

          ensureModel(model);

          tokensByModel[model].count++;
          tokensByModel[model].actualTokens += json.usageMetadata.totalTokenCount || 0;
          tokensByModel[model].completionTokens += json.usageMetadata.candidatesTokenCount || 0;
          tokensByModel[model].promptTokens += json.usageMetadata.promptTokenCount || 0;
        }
      });
    });

    if (execution.data) {
      const models = findAILanguageModel(execution.data);

      models.forEach((outerList, i) => {
        if (!Array.isArray(outerList)) {
          return;
        }

        outerList.forEach((innerList, ii) => {
          if (!Array.isArray(innerList)) {
            return;
          }

          innerList.forEach((item, iii) => {
            if (!item?.json) {
              return;
            }

            const model = resolveLanguageModelName(execution, item, i, ii, iii);
            const key = `llm_${nodeName}_${idx}_${i}_${ii}_${iii}`;

            llm_run_data[key] = item.json;

            ensureModel(model);

            tokensByModel[model].count++;
            tokensByModel[model].estimatedTokens += item.json.estimatedTokens || 0;

            if (item.json.tokenUsage) {
              tokensByModel[model].actualTokens += item.json.tokenUsage.totalTokens || 0;
              tokensByModel[model].completionTokens += item.json.tokenUsage.completionTokens || 0;
              tokensByModel[model].promptTokens += item.json.tokenUsage.promptTokens || 0;
            }
          });
        });
      });
    }
  });
});

return [
  {
    json: {
      all_nodes_summary,
      llm_run_data,
      tokensByModel,
    },
  },
];

const inputData = $input.first().json;

// Handle array input
const data = Array.isArray(inputData) ? inputData[0] : inputData;

// Get model names from tokensByModel
const models_used = data.tokensByModel ? Object.keys(data.tokensByModel) : [];

return [{
  json: {
    models_used: models_used
  }
}];

// 1. Extração da Data via all_nodes_summary
const summary = $json.all_nodes_summary || [];
const startTime = summary.length > 0 ? summary[0].startTime : Date.now();
const date = new Date(startTime);

// Formato ISO local (YYYY-MM-DD HH:mm:ss)
const executionDate = date.toISOString().replace('T', ' ').substring(0, 19);

// 2. Extração dos Custos (Objeto "cost" no seu JSON)
const costs = $json.cost || {};

return {
  execution_id: $executionId,
  execution_date: executionDate,
  // Valores numéricos absolutos
  total_input_cost_number: costs.input_cost || 0,
  total_output_cost_number: costs.output_cost || 0,
  total_costs_number: costs.total_cost || 0,
  // Timestamp original caso precise para ordenação
  timestamp: startTime
};

