let results = [];

for (const item of $input.all()) {
  let raw = item.json.output;

  raw = raw.trim();
  if (raw.startsWith("```json")) {
    raw = raw.slice(7);
  }
  if (raw.endsWith("```")) {
    raw = raw.slice(0, -3);
  }
  raw = raw.trim();

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    continue; // ignora se não for JSON válido
  }

  if (
    parsed &&
    parsed.title_trend &&
    parsed.trend &&
    parsed.title_alert &&
    parsed.alert &&
    parsed.title_strategy &&
    parsed.strategy
  ) {
    results.push({
      timestamp: now,
      ai_output: {
        title_trend: parsed.title_trend,
        trend: parsed.trend,
        title_alert: parsed.title_alert,
        alert: parsed.alert,
        title_strategy: parsed.title_strategy,
        strategy: parsed.strategy
      }
    });
  }
}

return results;

