const now = new Date().toISOString();

let raw = $input.all()[0].json.output;

if (!raw) return { timestamp: now, products: [] };

raw = raw.trim();
if (raw.startsWith("```json")) raw = raw.slice(7);
if (raw.endsWith("```")) raw = raw.slice(0, -3);
raw = raw.trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return { timestamp: now, error: "Falha ao parsear JSON" };
}

// Se o resultado for um array, usamos direto
// Caso venha dentro de um objeto { products: [...] }, também funciona
let products = [];
if (Array.isArray(parsed)) {
  products = parsed;
} else if (parsed.products && Array.isArray(parsed.products)) {
  products = parsed.products;
}

return { timestamp: now, products };

// n8n Code node (JavaScript)

const items = $input.all();

const uuidRegex =
  /\(([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\)/i;

const uuids = new Set();

for (const item of items) {
  const data = item.json?.data;
  if (!data || typeof data !== 'object') continue;

  for (const key of Object.keys(data)) {
    const match = key.match(uuidRegex);
    if (match) {
      uuids.add(match[1]);
    }
  }
}

return [
  {
    json: {
      uuids: Array.from(uuids),
    },
  },
];

const items = $input.all();

function parseProducts(productsRaw) {
  if (typeof productsRaw !== 'string') return null;

  // Remove ```json ... ``` wrappers
  const cleaned = productsRaw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    throw new Error('Invalid JSON inside products field');
  }
}

return items.map(item => {
  const uuids = Array.isArray(item.json.uuids) ? item.json.uuids : [];
  const uuidSet = new Set(uuids);

  const parsedProducts = parseProducts(item.json.products);

  if (!parsedProducts?.products) {
    return { json: item.json };
  }

  const cleanedProducts = parsedProducts.products.map(product => {
    const validDetails = (product.details || []).filter(d =>
      uuidSet.has(d.lead_id)
    );

    return {
      ...product,
      details: validDetails,
      conversations: validDetails.length
    };
  });

  return {
    json: {
      uuids,
      products: {
        products: cleanedProducts
      }
    }
  };
});

